scriptTask.script:
// Simula la llamada a un web service de reservas
if (String.valueOf(execution.getVariable('simularSinAulas')) == 'true') {
    println('[Reservar aula] el web service informa: sin aulas disponibles')
    throw new org.flowable.engine.delegate.BpmnError('SIN_AULAS', 'No hay aulas disponibles')
}
execution.setVariable('aulaGestionada', true)
execution.setVariable('aulaAsignada', 'AULA-101')
println('[Reservar aula] aula AULA-101 reservada para el curso ' + execution.getVariable('cursoId'))
